constants:
COMPARE_BASE="$(uv run python scripts/resolve_mutation_base.py \
  --event-name "workflow_dispatch" \
  --manual-base-sha "$MANUAL_BASE_SHA")"
{
  echo "## Manual mutation comparison base";
  echo "- Base: $COMPARE_BASE";
  echo "- Head: $(git rev-parse HEAD)";
} >> "$GITHUB_STEP_SUMMARY"
